require_once 'auth.php'; require_once 'auth_ui.php'; $message='';$error='';$devLink='';
if($_SERVER['REQUEST_METHOD']==='POST'){$email=strtolower(trim($_POST['email']??''));if(!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Enter a valid email address.';else{try{$db=auth_db();$s=$db->prepare('SELECT id,full_name,email FROM auth_users WHERE email=? AND is_active=1 LIMIT 1');$s->execute([$email]);$u=$s->fetch();if($u){$token=bin2hex(random_bytes(32));$hash=hash('sha256',$token);$db->prepare('UPDATE password_resets SET used_at=NOW() WHERE user_id=? AND used_at IS NULL')->execute([$u['id']]);$db->prepare('INSERT INTO password_resets(user_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(), INTERVAL 30 MINUTE))')->execute([$u['id'],$hash]);$scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http';$base=rtrim(dirname($_SERVER['SCRIPT_NAME']), '/\\');$link=$scheme.'://'.$_SERVER['HTTP_HOST'].$base.'/reset_password.php?token='.$token;$sent=@mail($email,'LabAsset password reset',"Hello {$u['full_name']},

Use this link to reset your password within 30 minutes:
{$link}

If you did not request this, ignore this email.",'From: LabAsset <no-reply@localhost>');if($sent)$message='If an active account matches that email, password reset instructions have been sent.';else{$message='For local development only: use the reset link below. Configure SMTP before deploying this system.';$devLink=$link;}}else{$message='If an active account matches that email, password reset instructions have been sent.';}}catch(Throwable $e){$error='Password reset is not configured yet. Import auth_setup.sql and confirm the database connection.';}}}
auth_page_start('Reset your password','We will help you securely regain access to your account.');if($error)echo '<div class="auth-alert error">'.h($error).'</div>';if($message)echo '<div class="auth-alert success">'.h($message).'</div>'; ?>
<form method="post" class="auth-form"><label for="email">Account email</label><input id="email" name="email" type="email" autocomplete="email" placeholder="you@organization.edu" required><button class="auth-submit" type="submit">Send reset instructions <span>→</span></button></form><?php if($devLink): ?><div class="dev-reset"><strong>Local development reset link</strong><p>Do not expose this link to other users. In production, configure authenticated SMTP and remove this development fallback.</p><a href="<?= h($devLink) ?>">Open password reset page</a></div><?php endif; ?><p class="auth-switch"><a href="login.php">← Back to sign in</a></p><?php auth_page_end(); ?>